#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [0.20017124, 0.033706415, 0.17538181], 'basis': [[0.0, 0.8915993912507074, 0.4528250495736384], [-0.9863214247104813, -0.07464068895716945, 0.1469653520700899], [0.1648333921178788, -0.44663104804006537, 0.8794035818493956]], 'axis': [0.4528250495736384, 0.1469653520700899, 0.8794035818493956], 'zmin': -0.07041985599980134, 'zmax': 0.05309610512703254, 'profiles': [{'outer': [[-0.10091310923525809, -0.04752604938176103], [-0.10226865095001418, -0.04176033886607164], [-0.09795280443465394, -0.0363002462508306], [-0.09021435192736806, -0.029270193149832376], [-0.08153320074261457, -0.019557216107546467], [-0.07163032959933097, -0.009595632645008088], [-0.05048655170541514, 0.007312746422036883], [-0.04581616836660238, 0.013209157308757435], [-0.03432092420628625, 0.027346138668194526], [-0.025569451705892487, 0.03342463167217971], [-0.019146586645224405, 0.03680031959521285], [-0.017900928054268614, 0.037620427776386134], [-0.0189125124476872, 0.039182817733517825], [-0.020096998001861655, 0.04622148390733187], [-0.01984382501969025, 0.052364449658518865], [-0.017283213731504068, 0.0606932504406951], [-0.010586755973001842, 0.06894733795910085], [-0.006493444342866073, 0.07384748615194622], [0.0007335587786036544, 0.07953310065411277], [0.00924207165872698, 0.0840174768461933], [0.012490306648618896, 0.08503594685533625], [0.026254435842703018, 0.08987863727027585], [0.035608588687959554, 0.09150363038584887], [0.04009004143269991, 0.09141371372412498], [0.0548684491017564, 0.09159171327553302], [0.06345372080990404, 0.09044688774744804], [0.07412083935416398, 0.08744076840486056], [0.08124841385467564, 0.0850007689422496], [0.08523138703706531, 0.08163882126854231], [0.08815789166452581, 0.07881704029204813], [0.09016435195177316, 0.07671000710271308], [0.09134020861068173, 0.07563072693372581], [0.09559456878470399, 0.06763780030759602], [0.09657077476951507, 0.06233606305913998], [0.0959086232673296, 0.05573481206726889], [0.0945996161875448, 0.047455991938466884], [0.09093228334330057, 0.03916264652952739], [0.08933017047373686, 0.03619725125853873], [0.09188637814343668, 0.018775917147238093], [0.09493260965462068, -0.0008587267860029862], [0.09489884517527052, -0.02746900803447577], [0.09380151697340237, -0.03902869145468595], [0.09255719402574858, -0.046837596635890925], [0.08843338395761778, -0.05820927827724897], [0.07999786714150241, -0.07165530377104146], [0.07553822738262092, -0.07614950376204116], [0.06995818018086038, -0.08098893276419059], [0.06348204287052647, -0.08215574355000482], [0.059868874080063174, -0.08041801041344716], [0.05581614293371184, -0.07767015682770785], [0.054487390112001, -0.07507987306982948], [0.05137204738092562, -0.07964141909525854], [0.04709248271256801, -0.08431166696630113], [0.04075618208967415, -0.08740955869573329], [0.03349960184958577, -0.08680495274249073], [0.02964432918794874, -0.08530727449545021], [0.02610024991486543, -0.08157112402411311], [0.024642558808765085, -0.08423140521077253], [0.01926251087048183, -0.087478219526969], [0.015020253360450935, -0.08850344657034989], [0.011994602055880469, -0.08866802665380202], [0.0005432926736578963, -0.08436660072239169], [-0.003068994149115263, -0.07944106350135786], [-0.0035513752122238065, -0.07442995608690622], [-0.007605302909114613, -0.08267221718559863], [-0.016303044884879127, -0.08470697929018582], [-0.02070096011249903, -0.08287099796837191], [-0.023593891754874537, -0.08137225563080393], [-0.027649539738058622, -0.08037678183428525], [-0.029789376282725055, -0.07944708952325998], [-0.03283329699018937, -0.07542868914978475], [-0.03323598082547916, -0.0720379805260262], [-0.03458402404952296, -0.052162955224619945], [-0.034241495734539044, -0.042349454735739964], [-0.034072858719374245, -0.04080006970247605], [-0.03400501096297511, -0.031873300600825945], [-0.034913953796581236, -0.032180032761710185], [-0.05260478649120745, -0.039171708628369696], [-0.06119648044112738, -0.046230842391069865], [-0.06788304719200076, -0.05251652463805098], [-0.07392322601426754, -0.05635739769966808], [-0.07980699494699282, -0.05816324737568128], [-0.08739152575755045, -0.05721139049327729], [-0.09117235253240177, -0.05527196113150655], [-0.09510652289766527, -0.05303421388154292]], 'holes': []}], 'simplify_tolerance': 3.976788514390585e-05, 'sketch_entity_count': 85}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
